def stats(arr):
    if not arr:
        return {"count": 0, "t_min": None, "t_max": None, "v_min": None, "v_max": None}

    times = []
    vals = []

    for p in arr:
        t = to_int_ms(p.get("Time"))
        v = to_float(p.get("Value"))
        if t is not None:
            times.append(t)
        if v is not None:
            vals.append(v)

    return {
        "count": len(arr),
        "t_min": min(times) if times else None,
        "t_max": max(times) if times else None,
        "v_min": min(vals) if vals else None,
        "v_max": max(vals) if vals else None
    }

